package com.narudzbine.identity.application;

import java.sql.Timestamp;
import java.time.*;
import java.time.temporal.ChronoUnit;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.*;

/** Retires expired capability secrets while preserving source/operation and original identity bindings. */
@Transactional(propagation=Propagation.MANDATORY)
public class ProofSecretRetention {
    private final JdbcTemplate jdbc;private final Clock clock;
    public ProofSecretRetention(JdbcTemplate jdbc,Clock clock){this.jdbc=jdbc;this.clock=clock;}
    private Timestamp cutoff(){return Timestamp.from(clock.instant().truncatedTo(ChronoUnit.MILLIS).minus(Duration.ofDays(30)));}
    public int reset(){return jdbc.update("WITH cutoff AS(SELECT ?::timestamptz AS at),expired AS(SELECT p.id FROM password_reset_proof p  CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at AND NOT(EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM password_reset_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RESET' AND b.source_id=p.id)) ORDER BY p.expires_at,p.id LIMIT 1000 FOR UPDATE OF p SKIP LOCKED) UPDATE password_reset_proof p SET token_hash=NULL FROM expired x WHERE p.id=x.id",cutoff());}
    public int email(){return jdbc.update("WITH cutoff AS(SELECT ?::timestamptz AS at),expired AS(SELECT p.id FROM email_change_proof p JOIN email_change e ON e.id=p.change_id CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND e.expires_at<=c.at AND e.created_at<=c.at AND NOT(e.state='RECONCILING' OR e.updated_at>c.at OR(p.verified_at IS NOT NULL AND p.verified_at>c.at) OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM email_change_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='EMAIL_PROOF' AND b.source_id=p.id)) ORDER BY e.expires_at,p.id LIMIT 1000 FOR UPDATE OF p SKIP LOCKED) UPDATE email_change_proof p SET token_hash=NULL FROM expired x WHERE p.id=x.id",cutoff());}
    public int setup(){return jdbc.update("WITH cutoff AS(SELECT ?::timestamptz AS at),expired AS(SELECT p.id FROM setup_email_proof p JOIN setup_invitation i ON i.id=p.invitation_id CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at AND NOT(p.generation>i.generation OR(p.generation=i.generation AND i.expires_at>c.at) OR EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=p.invitation_id AND(t.state NOT IN('COMPLETED','REJECTED') OR t.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM setup_delivery d WHERE d.proof_id=p.id AND(d.encrypted_token IS NOT NULL OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='SETUP' AND b.source_id=d.id)))) ORDER BY p.expires_at,p.id LIMIT 1000 FOR UPDATE OF p SKIP LOCKED) UPDATE setup_email_proof p SET token_hash=NULL FROM expired x WHERE p.id=x.id",cutoff());}
    public int device(){return jdbc.update("WITH cutoff AS(SELECT ?::timestamptz AS at),expired AS(SELECT p.id FROM device_verification p  CROSS JOIN cutoff c WHERE p.code_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at AND NOT(p.state IN('SENDING','UNKNOWN')) AND NOT(FALSE) ORDER BY p.expires_at,p.id LIMIT 1000 FOR UPDATE OF p SKIP LOCKED) UPDATE device_verification p SET code_hash=NULL FROM expired x WHERE p.id=x.id",cutoff());}
    public int oauth(){return jdbc.update("WITH cutoff AS(SELECT ?::timestamptz AS at),expired AS(SELECT p.id FROM external_challenge p  CROSS JOIN cutoff c WHERE p.encrypted_verifier IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at AND NOT(p.state='CLAIMED') AND NOT(FALSE) ORDER BY p.expires_at,p.id LIMIT 1000 FOR UPDATE OF p SKIP LOCKED) UPDATE external_challenge p SET encrypted_verifier=NULL FROM expired x WHERE p.id=x.id",cutoff());}
}
